function renderFlsm(){title('FLSM PLANNER','Divide a parent IPv4 network into equal-sized subnets. Select the results table, then Enter / Backspace to change the count.');content.insertAdjacentHTML('beforeend',`<div class="toolbar">${field('Parent IPv4 / CIDR:','parent','10.0.0.0/24')}${field('Subnets needed:','count',state.flsm,'number')}${btn('Calculate','calc')}${btn('Reset','reset')}${btn('Copy table','copy')}${btn('Export CSV','csv')}${btn('Export with Style','excel')}</div>${headers(['#','Network ID','CIDR','Subnet mask','First usable','Last usable','Broadcast','Usable hosts'])}${status()}${inventoryMarkup('flsm')}`);$('count').min=1;$('count').max=4096;function calc(){try{const c=ipv4cidr($('parent').value),n=Math.min(4096,Math.max(1,+$('count').value||1)),extra=Math.ceil(Math.log2(n)),p=c.p+extra;if(p>32)throw Error('Not enough addresses for that many subnets');const size=2**(32-p);renderRows(Array.from({length:n},(_,i)=>netRow(i+1,c.net+i*size,p)));state.flsm=n;checkpoint();setStatus(`Parent: ${ip4(c.net)}/${c.p}  |  Each subnet: /${p}, ${usable(0,p,size)[2]} usable hosts  |  ${n} shown, ${2**extra} possible equal subnets (${2**extra-n} unused).`)}catch(e){renderRows([]);setStatus(e.message,true)}}$('calc').onclick=calc;$('count').onchange=calc;$('parent').onchange=calc;$('results').tabIndex=0;$('results').title='Click a result, then press Enter to add or Backspace to remove a subnet';$('results').onclick=()=>{$('results').focus()};$('results').onkeydown=e=>{if(e.key!=='Enter'&&e.key!=='Backspace')return;if(e.target.closest('input,textarea,[contenteditable=true]'))return;e.preventDefault();e.stopPropagation();const current=Number($('count').value)||1;$('count').value=Math.max(1,Math.min(4096,current+(e.key==='Enter'?1:-1)));calc()};wireCombinedExports('IPv4-FLSM','flsm');wireReset('flsm');calc();setupInventory('flsm');enableColumnResize('flsm-results',content.querySelector('#results').closest('table'))}
function expand6(address){const str=address.toLowerCase().split('%')[0];if(!/^[a-f0-9:]+$/.test(str)||str.includes(':::'))throw Error('Invalid IPv6 address');const parts=str.split('::');if(parts.length>2)throw Error('Invalid IPv6 address');const left=parts[0]?parts[0].split(':'):[],right=parts.length===2&&parts[1]?parts[1].split(':'):[];if([...left,...right].some(p=>p.length>4||!p||!/^[a-f0-9]+$/.test(p)))throw Error('Invalid IPv6 block');const missing=8-left.length-right.length;if(parts.length===1?missing!==0:missing<1)throw Error('Invalid IPv6 address');return [...left,...Array(missing).fill('0'),...right].map(x=>x.padStart(4,'0'))}
function parse6(s){return BigInt('0x'+expand6(s).join(''))}
function format6(v){const parts=v.toString(16).padStart(32,'0').match(/.{4}/g).map(p=>parseInt(p,16).toString(16));let bestStart=-1,bestLen=0;for(let i=0;i<8;){if(parts[i]!=='0'){i++;continue}let j=i;while(j<8&&parts[j]==='0')j++;if(j-i>bestLen&&j-i>=2){bestStart=i;bestLen=j-i}i=j}if(bestStart<0)return parts.join(':');const l=parts.slice(0,bestStart).join(':'),r=parts.slice(bestStart+bestLen).join(':');return l+'::'+r}
